sqlGroup.select:
select a.id, a.`appKey`, a.`appSercet`, a.`dailyLimit`, a.`usedCnt`, date_format(a.`expireDate`,'%Y-%m-%d') as expireDate, a.status, b.dname as statusName, a.remark, a.`createTime`, a.creator
from sys_token a left join sys_dict b on b.dval=a.status and b.tcode='TOKEN_STATUS'
and a.appKey = #{appKey}
and a.appSercet = #{appSercet}
and a.status = #{status}
order by a.createTime desc
